import{_ as n,l as i,o as a,c,v as o,p as s,x as r,d,i as l,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"rename 原子性","description":"","frontmatter":{"title":"rename 原子性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rename-atomicity.md","filePath":"cs/rename-atomicity.md","lastUpdated":1789023840000}'),p={name:"cs/rename-atomicity.md"};function f(h,e,E,_,u,A){const t=i("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="rename-原子性" tabindex="-1">rename 原子性 <a class="header-anchor" href="#rename-原子性" aria-label="Permalink to &quot;rename 原子性&quot;">​</a></h1><div class="epigraph"><p>POSIX rename 要求：同一文件系统内，新名字要么完全指向新对象，要么仍是旧的；读者不应看见「两个名字都没有」的中间态。</p><footer>—— 据 POSIX rename；McKusick 对目录项更新与崩溃的讨论；ext4 对 rename 进事务的实践</footer></div><p><a href="/cs/inotify">上一课</a>把 rename 当成一对 cookie 事件。应用更关心：<strong>替换配置文件</strong>时，读者打开的是完整旧文件或完整新文件。缺口是 rename 的原子性与其实现依赖——目录项、链接计数、跨目录、跨 FS 失败。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写 <code>foo.tmp</code> 再 <code>rename(foo.tmp, foo)</code> 是经典发布手法：查找 <code>foo</code> 的人不应落到半截内容。POSIX：同挂载内 rename 覆盖已存在目标（非目录）是原子替换。跨设备返回 <code>EXDEV</code>，用户态才拷贝。缺口：内核如何把「删旧目录项、加新目录项、调整 <code>..</code>、减目标链接」收成一块；<a href="/cs/ext4-journal">日志</a> 与 <a href="/cs/cow-filesystem">COW</a> 如何保证崩溃后不是半改；软更新如何排序这两项。</p><p><span class="marginnote">目录 rename 还要改子目录 <code>..</code>，并防止把目录挂到自己的子孙下。whiteout 与 overlay 的 rename 另有规则，本课先钉底层 FS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ext4：rename 参加 JBD2 事务，目录块与 inode 一起提交。btrfs：新树根同时包含两项更新。无日志 FAT：两步目录项更新，崩溃可丢名或双名，靠 <a href="/cs/fsck">fsck</a>。VFS 先锁参与的目录 inode（锁序避免死锁），再调具体 <code>rename</code>。读者 lookup 要么看见旧 dentry 要么新的——<a href="/cs/dcache">dcache</a> 在事务/锁下更新。</p>',8)),(a(),s(m,null,{default:r(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22rename%20A%20to%20B%22%5D%20--%3E%20LOCK%5B%22%E9%94%81%E5%8F%82%E4%B8%8E%E7%9B%AE%E5%BD%95%22%5D%0A%20%20LOCK%20--%3E%20TX%5B%22FS%20%E4%BA%8B%E5%8A%A1%E6%88%96%20COW%20%E6%A0%B9%22%5D%0A%20%20TX%20--%3E%20VIS%5B%22lookup%20%E5%8F%AA%E8%A7%81%E6%97%A7%E6%88%96%E6%96%B0%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>rename 原子性把「发布」从字节拷贝里解放出来：内容早已 fsync 在临时 inode 上，名字切换才是可见点。它不保证跨文件的多对象原子（那要更上层事务）。不要把本课写成数据库 <code>UPDATE</code> 的 MVCC：对象是目录项。</p><p>与 <a href="/cs/nfs-semantics">NFS</a>：远程 rename 的原子性取决于服务器；客户端缓存可能短暂看见旧名。与 inotify：原子替换仍可能产生 DELETE+CREATE 或 MOVED_*，应用不能假设只有一种事件形状。</p><p>实现上：跨目录 rename 要锁两个目录，锁序按 inode 号避免死锁。目标若是非空目录，POSIX 失败；覆盖文件则减链接，可能把还打开的 inode 变成匿名。 读法上只引用<a href="/cs/inotify">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>rename 原子性</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>renameat2</code> 的 <code>RENAME_EXCHANGE</code>/<code>NOREPLACE</code> 全部标志当考纲，只承认它们改变失败条件，不改变「成功则原子」。下一课看不必落盘的树：tmpfs。</p><p>版本字段会变，课序钉的是机制对象「rename 原子性」，不是某一主线内核的结构体名。 后课默认：同 FS 内 rename 是名字发布点。纯内存文件系统如何实现同一套 VFS 操作，下一课 tmpfs。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同挂载 rename 对 lookup 原子；跨设备 EXDEV。</li><li>实现靠日志事务、COW 根或谨慎写序。</li><li>内存 FS 是下一课。</li><li>出处：POSIX；McKusick；ext4/btrfs rename 路径；<em>OSTEP</em>。</li></ul>',11))])}const T=n(p,[["render",f]]);export{P as __pageData,T as default};
